#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ptrace.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

/**
 * Function to create a new process with a specific PID using fork()
 */
pid_t create_process(pid_t pid) {
    pid_t pid_child = fork();
    if (pid_child == 0) {
        // Child process
        printf("Child process created with PID: %d\n", getpid());
        return pid_child;
    } else if (pid_child > 0) {
        // Parent process
        printf("Parent process created with PID: %d\n", getpid());
        return pid_child;
    } else {
        // Fork failed
        perror("fork");
        exit(EXIT_FAILURE);
    }
}

/**
 * Function to attach to a process using ptrace()
 */
int attach_process(pid_t pid) {
    if (ptrace(PTRACE_ATTACH, pid, NULL, NULL) == -1) {
        perror("ptrace");
        exit(EXIT_FAILURE);
    }
    return 0;
}

/**
 * Function to detach from a process using ptrace()
 */
int detach_process(pid_t pid) {
    if (ptrace(PTRACE_DETACH, pid, NULL, NULL) == -1) {
        perror("ptrace");
        exit(EXIT_FAILURE);
    }
    return 0;
}

/**
 * Function to manipulate memory using ptrace()
 */
int manipulate_memory(pid_t pid) {
    // Map a file into the process's memory space
    int fd = open("temp.txt", O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Map the file into the process's memory space
    void *addr = mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Modify the process's memory mapping
    char *data = (char *)addr;
    data[0] = 'X';

    // Detach from the process
    detach_process(pid);

    // Close the file descriptor
    close(fd);

    return 0;
}

int main() {
    // Create a new process with a specific PID
    pid_t pid = create_process(1234);

    // Attach to the process
    attach_process(pid);

    // Manipulate the process's memory
    manipulate_memory(pid);

    // Detach from the process
    detach_process(pid);

    return 0;
}
```

